/**
 * Editor configuration — all values are configurable constants.
 * Change AUTOSAVE_DEBOUNCE_MS to adjust how long after the last keystroke
 * an autosave is triggered.
 */

/** Milliseconds of inactivity before autosave fires. */
export const AUTOSAVE_DEBOUNCE_MS = 30_000;

/** Maximum excerpt length auto-generated from content. */
export const EXCERPT_MAX_CHARS = 280;
